// Differential harness: run the same argv through the Python executable and the
// Node port, compare stdout / stderr / exit status byte-for-byte.
//
// Cases are passed as a JSON file containing an array of argv arrays, e.g.
//   [["--a", "helloWorld"], ["--a="], []]
// Using spawn with an explicit argv array (no shell) means control characters,
// quotes and newlines reach both programs untouched.
//
//   node diff.mjs cases.json
//
// Prints one line per mismatch plus a summary; exits 1 if anything differed.

import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const PY = '/workspace/dataset/test17_executable';
const JS = '/output/test17.mjs';

function run(command, argv) {
  const result = spawnSync(command[0], [...command.slice(1), ...argv], {
    encoding: 'buffer',
    maxBuffer: 64 * 1024 * 1024,
    env: { ...process.env, COLUMNS: '80' },
  });
  return {
    status: result.status,
    stdout: result.stdout ?? Buffer.alloc(0),
    stderr: result.stderr ?? Buffer.alloc(0),
  };
}

function show(argv) {
  return JSON.stringify(argv);
}

function preview(buffer) {
  const text = buffer.toString('utf8');
  return JSON.stringify(text.length > 400 ? `${text.slice(0, 400)}...` : text);
}

const casesPath = process.argv[2];
if (!casesPath) {
  console.error('usage: node diff.mjs <cases.json>');
  process.exit(64);
}

const cases = JSON.parse(readFileSync(casesPath, 'utf8'));
if (!Array.isArray(cases)) {
  console.error('cases file must contain an array of argv arrays');
  process.exit(64);
}

let failures = 0;
for (const argv of cases) {
  const expected = run([PY], argv);
  const actual = run(['node', JS], argv);

  // The program name legitimately differs (argparse uses basename(argv[0]), so
  // the executable says "test17_executable" where the script says "test17.mjs").
  // Usage and error lines are compared with that one token normalised away.
  const normalise = (buffer, prog) => buffer.toString('utf8').split(prog).join('<PROG>');

  const problems = [];
  if (expected.status !== actual.status) {
    problems.push(`exit: py=${expected.status} js=${actual.status}`);
  }
  const expectedOut = normalise(expected.stdout, 'test17_executable');
  const actualOut = normalise(actual.stdout, 'test17.mjs');
  if (expectedOut !== actualOut) {
    problems.push(`stdout:\n    py=${preview(expected.stdout)}\n    js=${preview(actual.stdout)}`);
  }
  const expectedErr = normalise(expected.stderr, 'test17_executable');
  const actualErr = normalise(actual.stderr, 'test17.mjs');
  if (expectedErr !== actualErr) {
    problems.push(`stderr:\n    py=${JSON.stringify(expectedErr)}\n    js=${JSON.stringify(actualErr)}`);
  }

  if (problems.length > 0) {
    failures++;
    console.log(`MISMATCH ${show(argv)}`);
    for (const problem of problems) console.log(`  ${problem}`);
  }
}

console.log(`\n${cases.length - failures}/${cases.length} cases matched`);
process.exit(failures > 0 ? 1 : 0);

