  ['knife', 'knives'],
  ['life', 'lives'],
  ['wife', 'wives'],
  ['leaf', 'leaves'],
  ['half', 'halves'],
  ['wolf', 'wolves'],
  ['self', 'selves'],
  ['shelf', 'shelves'],
